        "status": "final",
        "code": {
          "text": "Jaw pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Pain for 3–4 weeks, left greater than right in the pre-auricular area; dull ache with a sharp twinge on wide opening or chewing. Pain is 3–4/10 at rest and up to 6/10 with chewing, improved from 8/10."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Reported history and associated symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No trauma or dental work. Possible nocturnal bruxism reported by husband. No headache, visual symptoms, scalp tenderness, jaw claudication, fever, weight loss, PMR symptoms, ear pain, neurological symptoms, or dental pain."
      }
    },
