        "code": {
          "text": "Temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Jaw opening and movement"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Jaw opening approximately 30–32 mm, with mild deviation to the left and pain at end range."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Jaw palpation and click"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Tenderness to palpation at the left TMJ and left masseter; mild right tenderness only on deep palpation. Soft, non-painful click on the left near full opening."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
